// ISS-SCHEMAEDIT-001: gen-types --check must flag orphan generated files, and stay clean at HEAD.
import test from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";
import { orphanGenerated } from "./gen-types.mjs";

test("orphanGenerated flags only banner-bearing files with no schema", () => {
  const dir = mkdtempSync(join(tmpdir(), "gt-"));
  try {
    writeFileSync(join(dir, "claims.ts"), "/* GENERATED by scripts/gen-types.mjs */\n");
    writeFileSync(join(dir, "gone.ts"), "/* GENERATED by scripts/gen-types.mjs */\n");
    writeFileSync(join(dir, "hand.ts"), "export const x = 1;\n");
    assert.deepEqual(orphanGenerated(dir, ["claims"]), [join(dir, "gone.ts")]);
    assert.deepEqual(orphanGenerated(join(dir, "missing"), ["claims"]), []);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test("gen-types --check passes on the committed tree", () => {
  const r = spawnSync(process.execPath, [new URL("./gen-types.mjs", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1"), "--check"], { encoding: "utf8" });
  assert.equal(r.status, 0, r.stderr);
});

// End-to-end: run the real CLI against a temp mini tree (GEN_TYPES_ROOT).
import { mkdirSync, existsSync, symlinkSync, readFileSync } from "node:fs";
const SCRIPT = new URL("./gen-types.mjs", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");
function mini() {
  const root = mkdtempSync(join(tmpdir(), "gtroot-"));
  mkdirSync(join(root, "schema"), { recursive: true });
  const gen = join(root, "packages", "core", "src", "generated");
  mkdirSync(gen, { recursive: true });
  writeFileSync(join(root, "schema", "things.schema.json"), JSON.stringify({ title: "Thing", type: "object", properties: { a: { type: "string" } } }));
  const run = (...a) => spawnSync(process.execPath, [SCRIPT, ...a], { encoding: "utf8", env: { ...process.env, GEN_TYPES_ROOT: root } });
  assert.equal(run().status, 0); // write: generates things.ts + index.ts
  assert.equal(run("--check").status, 0);
  return { root, gen, run };
}
const BANNER = "/* eslint-disable */\n/** GENERATED by scripts/gen-types.mjs from schema/gone.schema.json */\n";

test("e2e: --check fails on an orphan; write removes it; hand-written file survives", () => {
  const { root, gen, run } = mini();
  try {
    writeFileSync(join(gen, "gone.ts"), BANNER);
    writeFileSync(join(gen, "hand.ts"), "export const hand = 1;\n");
    const c = run("--check");
    assert.equal(c.status, 1);
    assert.match(c.stderr, /gone\.ts.*orphan/);
    assert.doesNotMatch(c.stderr, /hand\.ts/);
    assert.ok(existsSync(join(gen, "gone.ts")), "--check must not delete");
    assert.equal(run().status, 0);
    assert.ok(!existsSync(join(gen, "gone.ts")), "write removes the orphan");
    assert.equal(readFileSync(join(gen, "hand.ts"), "utf8"), "export const hand = 1;\n");
    assert.equal(run("--check").status, 0);
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test("e2e: a symlink to a banner-bearing file outside generated/ is never deleted", (t) => {
  const { root, gen, run } = mini();
  try {
    const outside = join(root, "outside.ts");
    writeFileSync(outside, BANNER);
    try { symlinkSync(outside, join(gen, "link.ts")); } catch { t.skip("symlink not permitted"); return; }
    assert.equal(run("--check").status, 0, "symlink is not a regular file, so not an orphan");
    assert.equal(run().status, 0);
    assert.ok(existsSync(outside), "target outside generated/ must survive");
    assert.ok(existsSync(join(gen, "link.ts")), "the link itself is left alone");
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test("e2e: a junction/dir named *.ts under generated/ is never read or deleted", () => {
  const { root, gen, run } = mini();
  try {
    const outDir = join(root, "outdir");
    mkdirSync(outDir);
    writeFileSync(join(outDir, "keep.txt"), "x");
    symlinkSync(outDir, join(gen, "junc.ts"), "junction");
    assert.equal(run("--check").status, 0);
    assert.equal(run().status, 0);
    assert.ok(existsSync(join(outDir, "keep.txt")));
    assert.ok(existsSync(join(gen, "junc.ts")));
  } finally { rmSync(join(root, "packages", "core", "src", "generated", "junc.ts"), { force: true, recursive: false }); rmSync(root, { recursive: true, force: true }); }
});
